import util from 'node:util'

import { docsUrl } from '@pnpm/cli.utils'
import { PnpmError } from '@pnpm/error'
import { createGetAuthHeaderByURI } from '@pnpm/network.auth-header'
import { createFetchFromRegistry, type CreateFetchFromRegistryOptions } from '@pnpm/network.fetch'
import type { Registries, RegistryConfig } from '@pnpm/types'
import { renderHelp } from 'render-help'

import { rcOptionsTypes } from './common.js'

export { rcOptionsTypes }

export function cliOptionsTypes (): Record<string, unknown> {
  return {
    ...rcOptionsTypes(),
  }
}

export const commandNames = ['ping']

export function help (): string {
  return renderHelp({
    description: 'Test connectivity to the configured npm registry.',
    url: docsUrl('ping'),
    usages: [
      'pnpm ping',
    ],
    descriptionLists: [
      {
        title: 'Options',
        list: [
          {
            description: 'The base URL of the npm registry to ping.',
            name: '--registry <url>',
          },
        ],
      },
    ],
  })
}

export interface PingOptions extends CreateFetchFromRegistryOptions {
  registry?: string
  registries?: Registries
  configByUri?: Record<string, RegistryConfig>
}

export async function handler (opts: PingOptions): Promise<string> {
  const registryUrl = opts.registry ?? opts.registries?.default ?? 'https://registry.npmjs.org/'
  const pingUrl = `${registryUrl.replace(/\/+$/, '')}/-/ping?write=true`

  const getAuthHeader = createGetAuthHeaderByURI(opts.configByUri ?? {}, registryUrl)
  const authHeader = getAuthHeader(registryUrl)
  const fetchFromRegistry = createFetchFromRegistry(opts)

  const start = Date.now()
  let response: Response
  try {
    response = await fetchFromRegistry(pingUrl, {
      authHeaderValue: authHeader,
    })
  } catch (err: unknown) {
    const message = util.types.isNativeError(err) ? err.message : String(err)
    throw new PnpmError('PING_FAILED', `Failed to reach registry ${registryUrl}: ${message}`)
  }

  if (!response.ok) {
    throw new PnpmError('PING_FAILED', `Failed to reach registry ${registryUrl}: ${response.status} ${response.statusText}`)
  }

  const time = Date.now() - start

  let details: Record<string, unknown> = {}
  try {
    details = await response.json() as Record<string, unknown>
  } catch {
    details = {}
  }

  let output = `PING ${registryUrl}\nPONG ${time}ms`
  if (details && typeof details === 'object' && Object.keys(details).length > 0) {
    output += `\n${JSON.stringify(details, null, 2)}`
  }
  return output
}

